package cl.dynasty.nexusbeacon.platform.classic;
import java.util.Collection;import java.util.HashMap;import java.util.HashSet;import java.util.Iterator;import java.util.Map;import java.util.Random;import java.util.Set;import org.bukkit.Bukkit;import org.bukkit.Location;import org.bukkit.Material;import org.bukkit.World;import org.bukkit.block.Block;import org.bukkit.block.CreatureSpawner;import org.bukkit.block.data.Ageable;import org.bukkit.configuration.file.FileConfiguration;import org.bukkit.entity.Animals;import org.bukkit.entity.Entity;import org.bukkit.entity.LivingEntity;import org.bukkit.entity.Monster;import org.bukkit.entity.Player;import org.bukkit.plugin.Plugin;import org.bukkit.potion.PotionEffect;import org.bukkit.scheduler.BukkitTask;import org.bukkit.util.Vector;
/** Synchronous, authoritative Classic productive-effect runtime. FurnaceBoost is event-driven. */
public final class ClassicEffectRuntime implements Runnable {
 private final Plugin plugin;private final ClassicApplicationState state;private final ClassicEffectCatalog catalog;private final FileConfiguration beacon;private final Map<String,Integer> cropCursors=new HashMap<String,Integer>();private final Map<String,ClassicSpawnerCountdown.State> spawnerCycles=new HashMap<String,ClassicSpawnerCountdown.State>();private final Random random=new Random();private BukkitTask task;private boolean running;private long scanGeneration;
 public ClassicEffectRuntime(Plugin plugin,ClassicApplicationState state,ClassicEffectCatalog catalog,FileConfiguration beacon,FileConfiguration effects){this.plugin=plugin;this.state=state;this.catalog=catalog;this.beacon=beacon;}
 public void start(){if(task!=null)return;running=true;long interval=Math.max(1L,beacon.getLong("beacon.tick-interval",40L));task=Bukkit.getScheduler().runTaskTimer(plugin,this,interval,interval);}public void close(){running=false;if(task!=null)task.cancel();task=null;cropCursors.clear();spawnerCycles.clear();}public boolean isRunning(){return running;}
 public void run(){if(!running)return;scanGeneration++;Set<String> ids=new HashSet<String>();for(ClassicBeaconRecord record:state.snapshot()){ids.add(record.getUniqueId().toString());if(!authoritative(record))continue;World world=Bukkit.getWorld(record.getLocation().getWorld());Location center=new Location(world,record.getLocation().getX(),record.getLocation().getY(),record.getLocation().getZ());for(String effectId:record.getActiveEffects()){ClassicEffectCatalog.Definition definition=catalog.get(effectId);Integer acquired=record.getEffects().get(effectId);if(definition==null||acquired==null)continue;int level=Math.min(definition.getMaxLevel(),Math.max(1,acquired.intValue()));try{execute(record,center,definition,level);}catch(RuntimeException failure){plugin.getLogger().warning("Classic effect "+effectId+" failed safely: "+failure.getClass().getSimpleName());}}}retain(ids);}
 private boolean authoritative(ClassicBeaconRecord r){World world=Bukkit.getWorld(r.getLocation().getWorld());return state.isAuthoritative(r)&&world!=null&&world.isChunkLoaded(r.getLocation().getX()>>4,r.getLocation().getZ()>>4)&&world.getBlockAt(r.getLocation().getX(),r.getLocation().getY(),r.getLocation().getZ()).getType()==Material.BEACON;}
 private void execute(ClassicBeaconRecord r,Location center,ClassicEffectCatalog.Definition d,int level){String type=d.getType();if("CROP_BOOST".equals(type))crop(r,center,d,level);else if("SPAWNER_BOOST".equals(type))spawner(r,center,d,level);else if(usesSharedEntityQuery(type)){if("POTION".equals(type))potion(r,center,d,level);else entities(r,center,d,level);}}
 private void potion(ClassicBeaconRecord r,Location center,ClassicEffectCatalog.Definition d,int level){PotionEffect effect=new PotionEffect(d.getPotion(),d.getDuration(),potionAmplifier(level,d.getAmplifier()),true,true);for(Entity entity:nearby(center,r.getRange()))if(entity instanceof LivingEntity&&inside(entity.getLocation(),center,r.getRange())&&target((LivingEntity)entity,d.getTarget()))((LivingEntity)entity).addPotionEffect(effect,true);}
 private void entities(ClassicBeaconRecord r,Location center,ClassicEffectCatalog.Definition d,int level){for(Entity entity:nearby(center,r.getRange())){if(!(entity instanceof Monster)||!inside(entity.getLocation(),center,r.getRange()))continue;LivingEntity living=(LivingEntity)entity;if("IGNITION".equals(d.getType()))living.setFireTicks(d.levelInt(level,"fire-ticks",60));else if("DAMAGE_FIELD".equals(d.getType()))living.damage(d.levelDouble(level,"damage",1D));else if("GRAVITY_PULSE".equals(d.getType())){Vector direction=center.clone().add(.5D,1D,.5D).toVector().subtract(living.getLocation().toVector());if(direction.lengthSquared()<=.01D)continue;direction.normalize().multiply(d.levelDouble(level,"pull-strength",.08D)).setY(d.levelDouble(level,"vertical-boost",.05D));Vector velocity=living.getVelocity().add(direction);double max=d.levelDouble(level,"max-velocity",1.2D);if(velocity.length()>max)velocity.normalize().multiply(max);living.setVelocity(velocity);}}}
 private void crop(ClassicBeaconRecord r,Location center,ClassicEffectCatalog.Definition d,int level){int radius=Math.max(0,Math.min(r.getRange(),beacon.getInt("performance.crop-boost.scan-radius",r.getRange()))),vertical=Math.max(0,beacon.getInt("performance.crop-boost.vertical-radius",8)),limit=Math.max(0,beacon.getInt("performance.crop-boost.max-blocks-per-tick",16)),scanLimit=Math.max(0,beacon.getInt("performance.crop-boost.max-scanned-blocks-per-tick",2000)),width=radius*2+1,total=width*width,minHeight=ClassicWorldHeightCompatibility.minimumHeight(center.getWorld());String key=r.getUniqueId()+":"+d.getId();int cursor=value(cropCursors.get(key)),grown=0,scanned=0,chance=d.levelInt(level,"growth-chance",15);while(total>0&&scanned<scanLimit&&grown<limit){int index=cursor%total,x=index/width-radius,z=index%width-radius;cursor++;scanned++;if(x*x+z*z>radius*radius)continue;int bx=center.getBlockX()+x,bz=center.getBlockZ()+z;if(!center.getWorld().isChunkLoaded(bx>>4,bz>>4))continue;for(int y=-vertical;y<=vertical;y++){int by=center.getBlockY()+y;if(!cropYValid(by,minHeight,center.getWorld().getMaxHeight()))continue;Block block=center.getWorld().getBlockAt(bx,by,bz);if(!(block.getBlockData() instanceof Ageable))continue;Ageable age=(Ageable)block.getBlockData();if(age.getAge()>=age.getMaximumAge()||random.nextDouble()*100D>chance)continue;age.setAge(Math.min(age.getMaximumAge(),age.getAge()+1));block.setBlockData(age,false);grown++;break;}}cropCursors.put(key,Integer.valueOf(cursor%total));}
 private void spawner(ClassicBeaconRecord r,Location center,ClassicEffectCatalog.Definition d,int level){if(spawnerConflict(beacon.getBoolean("performance.spawner-boost.disable-when-spawnermeta-enabled",true),Bukkit.getPluginManager().isPluginEnabled("SpawnerMeta")))return;int radius=Math.max(0,Math.min(r.getRange(),beacon.getInt("performance.spawner-boost.scan-radius",16))),vertical=Math.max(0,beacon.getInt("performance.spawner-boost.vertical-radius",radius)),limit=Math.max(0,beacon.getInt("performance.spawner-boost.max-blocks-per-tick",8)),scanLimit=Math.max(0,beacon.getInt("performance.spawner-boost.max-scanned-blocks-per-tick",2000)),processed=0,scanned=0,minHeight=ClassicWorldHeightCompatibility.minimumHeight(center.getWorld());long now=System.currentTimeMillis(),cooldown=cooldownMillis(d.levelInt(level,"cooldown-ticks",200));for(int x=-radius;x<=radius&&processed<limit&&scanned<scanLimit;x++)for(int y=-vertical;y<=vertical&&processed<limit&&scanned<scanLimit;y++)for(int z=-radius;z<=radius&&processed<limit&&scanned<scanLimit;z++){scanned++;int bx=center.getBlockX()+x,by=center.getBlockY()+y,bz=center.getBlockZ()+z;if(!spawnerYValid(by,minHeight,center.getWorld().getMaxHeight())||!center.getWorld().isChunkLoaded(bx>>4,bz>>4))continue;Block block=center.getWorld().getBlockAt(bx,by,bz);if(block.getType()!=Material.SPAWNER||!(block.getState() instanceof CreatureSpawner))continue;String key=block.getWorld().getName()+";"+bx+";"+by+";"+bz;CreatureSpawner spawner=(CreatureSpawner)block.getState();ClassicSpawnerCountdown.State cycle=spawnerCycles.get(key);if(cycle==null){cycle=new ClassicSpawnerCountdown.State();spawnerCycles.put(key,cycle);}int current=spawner.getDelay(),target=ClassicSpawnerCountdown.observe(cycle,current,spawner.getMinSpawnDelay(),spawner.getMaxSpawnDelay(),d.levelDouble(level,"speed-up-percentage",15D),random,scanGeneration,now,cooldown);if(target<current){spawner.setDelay(target);spawner.update(true);}processed++;}}
 private void retain(Set<String> ids){Iterator<String> it=cropCursors.keySet().iterator();while(it.hasNext()){String key=it.next();int split=key.lastIndexOf(':');if(split<0||!ids.contains(key.substring(0,split)))it.remove();}ClassicSpawnerCountdown.clean(spawnerCycles,scanGeneration);}
 static int boundedWork(int configured){return Math.max(0,configured);}static int potionAmplifier(int level,int perLevel){return Math.max(0,level*perLevel-1);}static boolean cropYValid(int y,int minimum,int maximum){return ClassicWorldHeightCompatibility.validY(y,minimum,maximum);}static boolean spawnerYValid(int y,int minimum,int maximum){return ClassicWorldHeightCompatibility.validY(y,minimum,maximum);}static boolean usesSharedEntityQuery(String type){return "POTION".equals(type)||"IGNITION".equals(type)||"DAMAGE_FIELD".equals(type)||"GRAVITY_PULSE".equals(type);}static double entityVerticalRadius(double centerY,int minimum,int maximum){return Math.max(centerY-minimum,maximum-centerY);}static boolean insideHorizontal(double dx,double dz,int range){return dx*dx+dz*dz<=range*range;}static int randomizedBaseDelay(int minimum,int maximum,Random random){int min=Math.max(1,minimum),max=Math.max(min+1,maximum);return random.nextInt(max-min)+min;}static int boostedSpawnerDelay(int base,double percent){double factor=Math.min(.95D,percent/100D);return Math.max(1,(int)Math.round(base*(1D-factor)));}static long cooldownMillis(int ticks){return Math.max(0,ticks)*50L;}static boolean spawnerConflict(boolean configured,boolean pluginEnabled){return configured&&pluginEnabled;}private static int value(Integer value){return value==null?0:value.intValue();}private static boolean inside(Location a,Location b,int range){return insideHorizontal(a.getX()-b.getX(),a.getZ()-b.getZ(),range);}private static Collection<Entity> nearby(Location center,int radius){World world=center.getWorld();double vertical=entityVerticalRadius(center.getY(),ClassicWorldHeightCompatibility.minimumHeight(world),world.getMaxHeight());return world.getNearbyEntities(center,radius,vertical,radius);}private static boolean target(LivingEntity entity,String target){return "ALL_ENTITIES".equals(target)||("PLAYERS".equals(target)&&entity instanceof Player)||("MONSTERS".equals(target)&&entity instanceof Monster)||("ANIMALS".equals(target)&&entity instanceof Animals);}
}
